const esc = s => String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const nb = s => esc(s).replace(/(^|\s)(и|а|в|во|с|со|к|о|у|на|по|за|из|до|от|не|без|для|при|или|—)\s/gi, (m, p, w) => p + w + ' ');
const item = s => { const t = nb(s); const i = t.indexOf(' —'); return i > 0 && i < 48 ? '<b>' + t.slice(0, i) + '</b>' + t.slice(i) : t; };
const KIND = { free: 'Бесплатно', freemium: 'Бесплатный тариф' };
const kindOf = s => /^freemium/i.test(s) ? 'freemium' : 'free';
const tag = (label, cls) => `<span class="tag ${cls}">${esc(label)}</span>`;
const sizeLines = v => v.split(' · ').map(x => x.charAt(0).toUpperCase() + x.slice(1));
const plural = (n, a, b, c) => { const m = n % 100, k = n % 10; return m > 10 && m < 20 ? c : k === 1 ? a : k > 1 && k < 5 ? b : c; };
const host = u => u.replace(/^https?:\/\/(www\.)?/, '').replace(/[?#].*$/, '').replace(/\/$/, '');
const logoSvg = () => document.getElementById('logo-mark').innerHTML;
const isMobile = () => window.matchMedia('(max-width:720px)').matches;

