/* ---------- блоки ---------- */
function resCard(b, s, id) {
  const k = kindOf(b.badge);
  const tags = tag(KIND[k], k) + (s.tag ? tag(s.tag, 'cat') : '');
  const inner = `<div class="top"><span class="ava" aria-hidden="true">${esc(b.name.charAt(0))}</span><h3>${esc(b.name)}</h3>${b.url ? EXT : ''}</div>
    <div class="tags">${tags}</div><p>${nb(b.desc)}</p>${b.url ? `<span class="url">${esc(host(b.url))}</span>` : ''}`;
  return b.url ? `<a class="res" id="${id}" href="${esc(b.url)}" target="_blank" rel="noopener nofollow">${inner}</a>` : `<div class="res" id="${id}">${inner}</div>`;
}
function fontCard(b, s, id) {
  const tags = tag('Бесплатно', 'free') + tag(b.script === 'lat' ? 'Латиница' : 'Кириллица', 'cat');
  return `<a class="res" id="${id}" href="${esc(b.url)}" target="_blank" rel="noopener nofollow">
    <div class="top"><span class="ava" aria-hidden="true">${esc(b.name.charAt(0))}</span><h3>${esc(b.name)}</h3>${EXT}</div>
    <div class="tags">${tags}</div><p>${nb(b.use)}</p>
    <div class="sizes"><div><small>Десктоп</small><span>${sizeLines(b.d).map(esc).join('<br>')}</span></div><div><small>Мобайл</small><span>${sizeLines(b.m).map(esc).join('<br>')}</span></div></div>
    <span class="url">${esc(host(b.url))}</span></a>`;
}
function block(b, slug, si, bi, s) {
  const id = `${slug}-${si}-${bi}`;
  if (b.type === 'res') return resCard(b, s, id);
  if (b.type === 'font') return fontCard(b, s, id);
  if (b.type === 'card') {
    const check = slug === 'checklists';
    return `<div class="card" id="${id}">${b.kicker ? `<div class="kick">${nb(b.kicker)}</div>` : ''}${b.title ? `<h3>${nb(b.title)}</h3>` : ''}
      <ul class="${check ? 'check' : ''}">${b.items.map((x, k) => `<li${check ? ` data-k="${id}-${k}" tabindex="0" role="checkbox" aria-checked="false"` : ''}>${item(x)}</li>`).join('')}</ul></div>`;
  }
  if (b.type === 'note') return `<div class="note" id="${id}">${nb(b.text)}</div>`;
  if (b.type === 'step') return `<div class="step" id="${id}">${slug === 'trends' && typeof ART !== 'undefined' ? `<div class="art">${(ART[/2027/.test(s.title) ? 't27' : 't26'] || [])[bi] || ''}</div>` : ''}<div class="n">${esc(b.num)}</div><h3>${nb(b.title)}</h3><p>${nb(b.desc)}</p></div>`;
  if (b.type === 'table') {
    const hl = k => b.head && b.head[k] === 'Актуально' ? ' class="hl"' : '';
    return `<div class="tbl" id="${id}"><table>${b.head ? `<thead><tr>${b.head.map((h, k) => `<th${hl(k)}>${esc(h)}</th>`).join('')}</tr></thead>` : ''}<tbody>${b.rows.map(r => `<tr>${r.map((c, k) => `<td${hl(k)}>${nb(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }
  return '';
}
const btext = b => [b.name, b.desc, b.use, b.title, b.text, b.kicker, (b.items || []).join(' '), (b.rows || []).map(r => r.join(' ')).join(' ')].filter(Boolean).join(' ').toLowerCase();

/* ---------- общие блоки ---------- */
function field(id, ph) {
  return `<div class="field" role="search">${LOUPE}<label class="sr" for="${id}">${esc(ph)}</label><input id="${id}" type="search" placeholder="${esc(ph)}" autocomplete="off"><button class="clear" type="button" aria-label="Очистить поиск">${CLEAR}</button></div>`;
}
function vkBanner() {
  return `<section class="bnr-sec"><div class="wrap"><a class="bnr vk js-vk" href="${LINKS.vk}" target="_blank" rel="noopener">
    <div class="bnr-body"><div class="bnr-txt"><h2 class="bnr-h">${isMobile() ? 'Больше пользы ищи во <span class="r">ВКонтакте</span>' : 'Больше пользы — во&nbsp;ВКонтакте'}</h2></div>
    <span class="hand">учу дизайну на задачах бизнеса</span>${IMG.kot ? `<img class="bnr-img" src="${IMG.kot}" alt="" width="200" height="245">` : ''}</div>
    <span class="bnr-act">Подписаться ${ARROW}</span></a></div></section>`;
}
function transitions() {
  return `<div class="wrap"><section class="trans">
   <div class="tr"><div><h3>Хочешь <span class="r">разобраться глубже</span>?</h3><p>${nb('Справочник отвечает на вопрос «что взять», а обучение — «как и почему».')}</p><p class="b">${nb('От основ UX/UI до дизайн-системы.')}</p></div>
    <a class="btn btn-sec js-edu" href="${LINKS.edu}" target="_blank" rel="noopener">Узнать об обучении ${ARROW}</a></div>
   <div class="tr"><div><h3>Нужен <span class="r">дизайн сайта</span> или <span class="r">приложения</span>?</h3><p>${nb('Проектирую сайты, приложения и дизайн-системы.')}</p><p class="b">${nb('Отдаю макеты, которые команда сразу берёт в разработку.')}</p></div>
    <a class="btn btn-sec js-project" href="${LINKS.project}" target="_blank" rel="noopener">Обсудить проект ${ARROW}</a></div>
  </section></div>`;
}
function trendsBanner() {
  const tp = PAGES.find(p => p.slug === 'trends'); if (!tp) return '';
  const si = tp.sections.findIndex(s => /2027/.test(s.title));
  return `<section class="bnr-sec"><div class="wrap"><a class="bnr t27" href="#/s/trends/trends-${si}">
    <div class="bnr-body"><div class="bnr-txt"><h2 class="bnr-h">Тренды <span class="big">20<span class="ol">27</span></span></h2>
     <p>${nb('Куда движутся интерфейсы в следующем году: агенты, доверие к ИИ, авторский визуал и ещё 6 направлений.')}</p></div>
     <span class="hand">горячие тренды<br>следующего года</span>
     ${IMG.trendD ? `<img class="bnr-img img-d" src="${IMG.trendD}" alt="" width="428" height="376">` : ''}${IMG.trendM ? `<img class="bnr-img img-m" src="${IMG.trendM}" alt="" width="342" height="427" loading="lazy">` : ''}</div>
    <span class="bnr-act">Смотреть тренды ${ARROW}</span></a></div></section>`;
}

